  url=base+'?prefix='+urllib.parse.quote(prefix,safe='')+'&maxResults=1000'
  try:
    data=json.loads(urllib.request.urlopen(url, timeout=30).read())
    print('PREFIX', prefix, 'count', len(data.get('items',[])))
    for it in data.get('items',[])[:20]:
      print(it['name'], it.get('size'))
  except Exception as e:
    print('ERR', prefix, e)
