/bin/bash -lc "python3 - <<'PY'
import urllib.request, urllib.parse, json
base='https://storage.googleapis.com/storage/v1/b/gcp-public-data--gnomad/o'
for prefix in ['release/3.1/vcf/hgdp_tgp/', 'release/3.1/vcf/', 'release/3.1.2/', 'release/3.1/', 'release/']:
  url=base+'?prefix='+urllib.parse.quote(prefix,safe='')+'&maxResults=1000'
  try:
    data=json.loads(urllib.request.urlopen(url, timeout=60).read())
    items=data.get('items',[])
    print('PREFIX', prefix, 'count', len(items))
    for it in items:
      name=it['name']
      if any(k in name.lower() for k in ['hgdp','tgp','chr1']):
        print(' ', name, it.get('size'))
  except Exception as e:
    print('ERR', prefix, e)
PY"

